    (477::BIGINT, 'Excelente profesora ,hace todo lo posible por aclarar dudas y super simpática'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-13T00:00:00+00:00'::TIMESTAMPTZ, '4f85493ccaccb12492d81a0a62e8b99957f4bfeb150f444b2a45309cefb79c72'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelentes y divertidas clases, recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'ba45c8e524d183ec5397baa48253be6c2c93db5f1f28746c2680dca995a6e50f'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Es una excelente profesora, hace que entiendas la materia de una manera fácil. Califica bien y es buena gente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-02T00:00:00+00:00'::TIMESTAMPTZ, '87e3f0ffc69c2314418e13f4d8288c10db93b2dff086ad14f548851493232a2b'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Es buena gente y explica bien, es como una profesora de colegio. Tiene paciencia y es graciosa, le da buen ambiente a la clase. La recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-15T00:00:00+00:00'::TIMESTAMPTZ, '737f7428d58bb8ecbec488c7cd171a5a82f49357e05652c31ae4c7dfb19b22d3'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
